_ASCII_DIGITS = frozenset('0123456789')
_PREFIX = 'bytes='


def _is_decimal(text):
    return bool(text) and all(c in _ASCII_DIGITS for c in text)


def parse(header):
    if not isinstance(header, str) or not header.startswith(_PREFIX):
        return None
    parts = header[len(_PREFIX):].split('-')
    if len(parts) != 2:
        return None
    first, last = parts
    if not first and not last:
        return None
    if first and not _is_decimal(first):
        return None
    if last and not _is_decimal(last):
        return None
    start = int(first) if first else None
    end = int(last) if last else None
    return start, end


def bounds(header, length):
    parsed = parse(header)
    if parsed is None or length == 0:
        return None
    start, end = parsed
    if start is None:
        if end == 0:
            return None
        start = max(0, length - end)
        end = length - 1
    else:
        if start >= length:
            return None
        if end is not None:
            end = min(end, length - 1)
        else:
            end = length - 1
    if start > end:
        return None
    return start, end

